public void setZeroes(int[][] matrix) {
    int m = matrix.length, n = matrix[0].length;
    int[][] copy = new int[m][n];
    for (int i = 0; i < m; i++) {
        copy[i] = matrix[i].clone();
    }
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (copy[i][j] == 0) {
                for (int c = 0; c < n; c++) matrix[i][c] = 0;
                for (int r = 0; r < m; r++) matrix[r][j] = 0;
            }
        }
    }
}

